import sys

def min_final_health(N, A):
    A.sort(reverse=True)
    while len(A) > 1:
        A[1] -= A[0]
        if A[1] <= 0:
            A.pop(1)
        else:
            A[0], A[1] = A[1], A[0]
    return A[0]

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))
    print(min_final_health(N, A))
